ssize_t read_from_socket(struct file *file, char __user *buf, size_t count, loff_t *ppos) {
    ssize_t bytes_read = 0;
    struct socket *sock = file->private_data;
    struct sk_buff *skb;

    if (!sock) {
        return -EINVAL;
    }

    if (file->f_flags & O_NONBLOCK) {
        if (skb_queue_empty(&sock->sk->sk_receive_queue)) {
            return -EAGAIN;
        }
    }

    if (!buf || count == 0) {
        return -EINVAL;
    }

    skb = skb_dequeue(&sock->sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (skb->len > count) {
        kfree_skb(skb);
        return -EINVAL;
    }

    if (copy_to_user(buf, skb->data, skb->len)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    bytes_read = skb->len;
    kfree_skb(skb);
    return bytes_read;
}
